import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transform
  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);

    if (pos.rotationXYZ) {
      const [rx, ry, rz] = pos.rotationXYZ;
      group.rotation.order = 'XYZ';
      group.rotation.set(rx, ry, rz);
    }

    if (pos.scaleXYZ) {
      const [sx, sy, sz] = pos.scaleXYZ;
      group.scale.set(sx, sy, sz);
    }
  }

  // Load texture for plane
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry (aspect 512:320 = 1.6:1)
  const aspect = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // Material for textured plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    toneMapped: false
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textConfig = config.textContent[0];
    if (textConfig.text) {
      const textMesh = ctx.fontAtlas.renderText(textConfig.text, {
        fontSize: 0.13,
        fontFamily: 'JetBrains Mono',
        fontWeight: 400,
        color: 0x16161d,
        alignment: 'left'
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        group.add(textMesh);
      }
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
